function validate([rec1, rec2]) {
  for (const rec of [rec1, rec2]) {
    if (!Array.isArray(rec) || rec.length !== 4) return 'Each rectangle has exactly 4 numbers.';
    if (rec.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Coordinates are whole numbers from -10^9 to 10^9.';
    if (rec[0] >= rec[2] || rec[1] >= rec[3]) return 'Each rectangle needs x1 < x2 and y1 < y2.';
  }
  return null;
}

