function isRectangleOverlap(rec1, rec2) {
  // Cut the plane along every edge coordinate and test the centre of each small cell against both rectangles.
  const xs = [...new Set([rec1[0], rec1[2], rec2[0], rec2[2]])].sort((a, b) => a - b);
  const ys = [...new Set([rec1[1], rec1[3], rec2[1], rec2[3]])].sort((a, b) => a - b);
  const inside = (rec, x, y) => rec[0] < x && x < rec[2] && rec[1] < y && y < rec[3];
  for (let i = 0; i + 1 < xs.length; i++) {
    for (let j = 0; j + 1 < ys.length; j++) {
      const x = (xs[i] + xs[i + 1]) / 2;
      const y = (ys[j] + ys[j + 1]) / 2;
      if (inside(rec1, x, y) && inside(rec2, x, y)) return true;
    }
  }
  return false;
}

