function generate(rand, size) {
  const span = size === 'large' ? 1000000000 : 4;
  const pick = () => Math.floor(rand() * (2 * span + 1)) - span;
  const interval = () => {
    for (;;) {
      const a = pick();
      const b = pick();
      if (a !== b) return [Math.min(a, b), Math.max(a, b)];
    }
  };
  const rect = () => {
    const [x1, x2] = interval();
    const [y1, y2] = interval();
    return [x1, y1, x2, y2];
  };
  return [rect(), rect()];
}
